import java.nio.file.Path;
import java.security.SecureRandom;
import java.time.Clock;
import java.util.Map;
import java.util.concurrent.Executors;

/** Relay management/health process. Opaque WSS routing is hosted by {@link RelayWebSocketServer}. */
public final class RelayApplication implements AutoCloseable {
    private final SqliteRelayMetadataStore store;
    private final RelayPairingService pairing;
    private final RelayRouter router;
    private final HttpServer http;
    private final RelayWebSocketServer webSocket;
    private final ObjectMapper mapper = new ObjectMapper();

    private RelayApplication(Path dataDirectory, String bind, int port) throws IOException {
        store = new SqliteRelayMetadataStore(dataDirectory.resolve("relay.db"));
        pairing = new RelayPairingService(store, Clock.systemUTC(), new SecureRandom());
        router = new RelayRouter(store, Clock.systemUTC(), RelayRouter.Quotas.defaults());
        http = HttpServer.create(new InetSocketAddress(bind, port), 0);
        http.setExecutor(Executors.newThreadPerTaskExecutor(Thread.ofVirtual().name("ji-relay-http-", 0).factory()));
        http.createContext("/api/v1/health/live", exchange -> health(exchange, "live"));
        http.createContext("/api/v1/health/ready", exchange -> health(exchange, "ready"));
        http.createContext("/api/v1/version", this::version);
        http.createContext("/api/v1/bootstrap", this::bootstrap);
        http.createContext("/metrics", this::metrics);
        webSocket = new RelayWebSocketServer(router, bind, port + 1);
        webSocket.start();
        http.start();
    }

